1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import {
5|  AMBIENCES,
6|  DEFAULT_AMBIENCE_VOLUME,
7|  ambienceLabel,
8|  levelById,
9|  nextLevel,
10|} from "@/core/ambience";
11|import { loadAmbiencePrefs, saveAmbiencePrefs } from "./ambience-prefs";
12|import { AmbienceController } from "./ambience-controller";
13|import { WebAmbienceEngine } from "./ambience-engine";
14|import { Icon } from "./icons";
15|import type { RainIconName } from "./icons-rain";
16|import { DEFAULT_SKIN, isSkinId, type SkinId } from "./skin";
17|
18|const RAIN = AMBIENCES[0]!;
19|
20|// One drop cycle: how long the button replays its animation after a click.
21|const ANIM_MS = 1400;
22|
23|// The button owns its controller: it loads prefs once, saves on change,
24|// and starts the stored level on the first gesture anywhere in the page.
25|export function RainAmbience({ muted }: { muted: boolean }) {
26|  const controllerRef = useRef<AmbienceController | null>(null);
27|  const [level, setLevel] = useState("off");
28|  const [volume, setVolume] = useState(DEFAULT_AMBIENCE_VOLUME);
29|  const [burst, setBurst] = useState(0);
30|  // Server render uses the default so hydration matches; the live data-skin
31|  // value applies on mount.
32|  const [skin, setSkin] = useState<SkinId>(DEFAULT_SKIN);
33|  const burstTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
34|
35|  useEffect(() => {
36|    const current = document.documentElement.dataset.skin;
37|    if (isSkinId(current)) setSkin(current);
38|  }, []);
39|
40|  useEffect(() => {
41|    const controller = new AmbienceController(new WebAmbienceEngine());
42|    controllerRef.current = controller;
43|    const prefs = loadAmbiencePrefs();
44|    if (prefs) {
45|      controller.setVolume(prefs.volume);
46|      setVolume(prefs.volume);
47|      if (prefs.level !== "off" && levelById(RAIN, prefs.level)) {
48|        controller.setLevel(prefs.level);
49|        setLevel(prefs.level);
50|      }
51|    }
52|    const unlock = () => void controller.unlock();
53|    document.addEventListener("pointerdown", unlock, { once: true });
54|    document.addEventListener("keydown", unlock, { once: true });
55|    return () => {
56|      document.removeEventListener("pointerdown", unlock);
57|      document.removeEventListener("keydown", unlock);
58|      controller.dispose();
59|      controllerRef.current = null;
60|    };
61|  }, []);
62|
63|  useEffect(() => {
64|    controllerRef.current?.setMuted(muted);
65|  }, [muted]);
66|
67|  useEffect(
68|    () => () => {
69|      if (burstTimer.current) clearTimeout(burstTimer.current);
70|    },
71|    [],
72|  );
73|
74|  function cycle() {
75|    const controller = controllerRef.current;
76|    if (!controller) return;
77|    void controller.unlock();
78|    const id = nextLevel(RAIN, level);
79|    controller.setLevel(id);
80|    setLevel(id);
81|    saveAmbiencePrefs({ level: id, volume });
82|    setBurst((b) => b + 1);
83|    if (burstTimer.current) clearTimeout(burstTimer.current);
84|    burstTimer.current = setTimeout(() => setBurst(0), ANIM_MS);
85|  }
86|
87|  function changeVolume(value: number) {
88|    controllerRef.current?.setVolume(value);
89|    setVolume(value);
90|    saveAmbiencePrefs({ level, volume: value });
91|  }
92|
93|  const label = ambienceLabel(RAIN, level);
94|  return (
95|    <>
96|      <button
97|        type="button"
98|        className="skip rain"
99|        data-level={level}
100|        data-anim={burst ? "1" : undefined}
101|        onClick={cycle}
102|        aria-label={label}
103|        title={label}
104|      >
105|        {/* key replays the one-shot animation on rapid clicks */}
106|        <span className="face" key={burst}>
107|          <Icon name={`rain-${level}` as RainIconName} skin={skin} />
108|        </span>
109|      </button>
110|      {level !== "off" ? (
111|        <input
112|          type="range"
113|          className="rain-volume"
114|          min={0}
115|          max={1}
116|          step={0.05}
117|          value={volume}
118|          onChange={(e) => changeVolume(Number(e.target.value))}
119|          aria-label="Rain volume"
120|        />
121|      ) : null}
122|    </>
123|  );
124|}

