1|import { initialTheme, THEME_KEY, THEME_SCRIPT } from "./theme";
2|import { describe, expect, it } from "vitest";
3|
4|describe("initialTheme", () => {
5|  it("defaults to light without an explicit stored choice", () => {
6|    expect(initialTheme(null)).toBe("light");
7|    expect(initialTheme("garbage")).toBe("light");
8|    expect(initialTheme("light")).toBe("light");
9|    expect(initialTheme("dark")).toBe("dark");
10|  });
11|
12|  it("inline script starts in light and never reads the OS preference", () => {
13|    expect(THEME_SCRIPT).not.toContain("prefers-color-scheme");
14|    expect(THEME_SCRIPT).not.toContain("matchMedia");
15|    expect(THEME_SCRIPT).toContain("lectoria.theme");
16|    expect(initialTheme(null)).toBe("light");
17|  });
18|
19|  it("builds the inline script from THEME_KEY", () => {
20|    expect(THEME_KEY).toBe("lectoria.theme");
21|    expect(THEME_SCRIPT).toContain(JSON.stringify(THEME_KEY));
22|  });
23|
24|  it("inline script resolves stored values to a data-theme", () => {
25|    const run = (stored: unknown): string => {
26|      let theme = "";
27|      const localStorage = {
28|        getItem: () => {
29|          if (stored === "throw") throw new Error("denied");
30|          return stored;
31|        },
32|      };
33|      const document = {
34|        documentElement: {
35|          setAttribute: (_key: string, value: string) => {
36|            theme = value;
37|          },
38|        },
39|      };
40|      new Function("localStorage", "document", THEME_SCRIPT)(localStorage, document);
41|      return theme;
42|    };
43|    expect(run(null)).toBe("light");
44|    expect(run("garbage")).toBe("light");
45|    expect(run("dark")).toBe("dark");
46|    expect(run("light")).toBe("light");
47|    expect(run("throw")).toBe("light");
48|  });
49|});

