1|import { describe, expect, it } from "vitest";
2|import { DEFAULT_SKIN, isSkinId, SKINS, SKIN_SCRIPT } from "./skin";
3|
4|describe("skin", () => {
5|  it("ships the three rain-button skins with engraving first", () => {
6|    expect(SKINS).toEqual(["engraving", "watercolor", "ink"]);
7|    expect(DEFAULT_SKIN).toBe("engraving");
8|  });
9|
10|  it("accepts only known skin ids", () => {
11|    expect(isSkinId("engraving")).toBe(true);
12|    expect(isSkinId("watercolor")).toBe(true);
13|    expect(isSkinId("ink")).toBe(true);
14|    expect(isSkinId("default")).toBe(false);
15|    expect(isSkinId(undefined)).toBe(false);
16|    expect(isSkinId(null)).toBe(false);
17|  });
18|
19|  it("inline script applies a valid ?skin= value and ignores the rest", () => {
20|    const run = (search: string): string | undefined => {
21|      let skin: string | undefined;
22|      new Function("location", "document", SKIN_SCRIPT)(
23|        { search },
24|        {
25|          documentElement: {
26|            dataset: {
27|              set skin(v: string) {
28|                skin = v;
29|              },
30|            },
31|          },
32|        },
33|      );
34|      return skin;
35|    };
36|    expect(run("?skin=watercolor")).toBe("watercolor");
37|    expect(run("?skin=ink")).toBe("ink");
38|    expect(run("?skin=engraving")).toBe("engraving");
39|    expect(run("?skin=default")).toBe(undefined);
40|    expect(run("?skin=")).toBe(undefined);
41|    expect(run("")).toBe(undefined);
42|    expect(run("?other=1")).toBe(undefined);
43|  });
44|
45|  it("inline script never throws and stays in sync with SKINS", () => {
46|    expect(SKIN_SCRIPT).toContain("try");
47|    expect(SKIN_SCRIPT).toContain(JSON.stringify(SKINS));
48|  });
49|});

